using System;
using System.IO;
using NUnit.Framework;
using NUnit.Framework.Interfaces;
using OpenQA.Selenium.Appium;
using OpenQA.Selenium.Appium.Windows;

namespace MiniSumTests.AIGenerated
{
    [TestFixture]
    public class AIScriptTests
    {
        private WindowsDriver<WindowsElement> _driver;

        [SetUp]
        public void Setup()
        {
            var options = new AppiumOptions();
            var appPath = Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, @"..\..\..\..\case-study-app\MiniSum.exe"));
            options.AddAdditionalCapability("app", appPath);
            options.AddAdditionalCapability("deviceName", "WindowsPC");
            _driver = new WindowsDriver<WindowsElement>(new Uri("http://127.0.0.1:4723"), options);
            _driver.Manage().Timeouts().ImplicitWait = TimeSpan.FromSeconds(3);
        }

        [Test]
        public void Test_Login_And_Calculate_Success()
        {
            // Login
            _driver.FindElementByAccessibilityId("txtUser").SendKeys("admin");
            _driver.FindElementByAccessibilityId("txtPass").SendKeys("1234");
            _driver.FindElementByAccessibilityId("btnLogin").Click();

            // Calculate
            var txtA = _driver.FindElementByAccessibilityId("txtA");
            var txtB = _driver.FindElementByAccessibilityId("txtB");
            txtA.Clear();
            txtA.SendKeys("25");
            txtB.Clear();
            txtB.SendKeys("75");
            _driver.FindElementByAccessibilityId("btnSum").Click();

            var lblResult = _driver.FindElementByAccessibilityId("lblResult");
            Assert.AreEqual("Ket qua: 25 + 75 = 100", lblResult.Text);
        }

        [TearDown]
        public void Cleanup()
        {
            if (TestContext.CurrentContext.Result.Outcome.Status == TestStatus.Failed)
            {
                var screenshot = _driver.GetScreenshot();
                screenshot.SaveAsFile($"Failed_{TestContext.CurrentContext.Test.Name}.png");
            }
